package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem string // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct int64 // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.Zero // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var DiscRecData DiscRec

var discFile *os.File
var discScanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10Int64(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func parsePriceField(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return decimal.Zero
	}
	return decimal.New(n, -2)
}

func parsePctField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	m := n % 100
	if m < 0 {
		m += 100
	}
	return m
}

func fitPic9V(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	modScaled := decimal.New(1, int32(intDigits+scale))
	scaled := v.Shift(int32(scale)).Truncate(0)
	r := scaled.Mod(modScaled)
	if r.IsNegative() {
		r = r.Add(modScaled)
	}
	return r.Shift(int32(-scale))
}

func formatEdited(v decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := len(fracPic)
	N := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			N++
		}
	}
	a := v.Abs().Truncate(int32(fracDigits))
	scaled := a.Shift(int32(fracDigits)).Truncate(0).IntPart()
	powFrac := int64(1)
	for i := 0; i < fracDigits; i++ {
		powFrac *= 10
	}
	var intPart, fracPart int64
	if fracDigits > 0 {
		intPart = scaled / powFrac
		fracPart = scaled % powFrac
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		intPart = scaled
		fracPart = 0
	}
	modInt := int64(1)
	for i := 0; i < N; i++ {
		modInt *= 10
	}
	if modInt != 0 {
		intPart = intPart % modInt
	}
	intDigitsStr := fmt.Sprintf("%0*d", N, intPart)
	var sb strings.Builder
	digitIdx := 0
	suppressed := true
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			d := intDigitsStr[digitIdx]
			digitIdx++
			if c == 'Z' {
				if suppressed && d == '0' {
					sb.WriteByte(' ')
				} else {
					sb.WriteByte(d)
					suppressed = false
				}
			} else {
				sb.WriteByte(d)
				suppressed = false
			}
		} else if c == ',' {
			if suppressed {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else {
			sb.WriteRune(c)
		}
	}
	if dotIdx >= 0 {
		sb.WriteByte('.')
		fracStr := fmt.Sprintf("%0*d", fracDigits, fracPart)
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func MainPara() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	discScanner = bufio.NewScanner(discFile)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	discScanner.Buffer(buf, maxCap)
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	discFile.Close()
	SummaryPara()
}

func ReadPara() {
	if !discScanner.Scan() {
		if err := discScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
		return
	}
	line := discScanner.Text()
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	DiscRecData.DrItem = line[0:6]
	DiscRecData.DrPrice = parsePriceField(line[6:13])
	DiscRecData.DrPct = parsePctField(line[13:15])
}

func ProcessPara() {
	tmp := DiscRecData.DrPrice.Mul(decimal.NewFromInt(DiscRecData.DrPct)).Shift(-2)
	tmpR := tmp.Round(2)
	WsDiscount = fitPic9V(tmpR, 5, 2)
	tmp2 := DiscRecData.DrPrice.Sub(WsDiscount).Truncate(2)
	WsNet = fitPic9V(tmp2, 5, 2)
	tmpTot := WsTotalNet.Add(WsNet).Truncate(2)
	WsTotalNet = fitPic9V(tmpTot, 8, 2)
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatEdited(DiscRecData.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	pctStr := fmt.Sprintf("%02d", DiscRecData.DrPct%100)
	out := DiscRecData.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprintln(os.Stdout, out)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount%1000)
	out := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, out)
}

func main() {
	MainPara()
}
